import numpy as np
A = np.array([1.0, 12.0])                 # f = 0.5*(x^2 + 12 y^2)
grad = lambda p: A * p
def sgd(lr=0.15, n=40):
    p = np.array([-4.0, 1.5])
    for _ in range(n): p = p - lr * grad(p)
    return p
def momentum(lr=0.03, beta=0.9, n=40):
    p, v = np.array([-4.0, 1.5]), np.zeros(2)
    for _ in range(n):
        v = beta * v - lr * grad(p)       # 速度（勾配の移動平均）
        p = p + v
    return p
for name, p in [('SGD', sgd()), ('Momentum', momentum())]:
    print(name, np.round(p, 4), 'f =', round(0.5 * (A * p ** 2).sum(), 5))
